class _Cache_shared_shared_803816:
    """Simple LRU cache."""
    def __init__(self, maxsize=100):
        self._cache = shared_shared_803816
        self._order = []
        self._max = maxsize
    def get(self, key):
        if key in self._cache:
            self._order.remove(key)
